<?php

declare(strict_types=1);

require_once __DIR__.'/Database.php';
require_once __DIR__.'/Auth.php';
require_once __DIR__.'/AccessPolicy.php';
require_once __DIR__.'/AppNavigation.php';
require_once __DIR__.'/RegistrationService.php';

final class RegistrationOperationsExperience
{
    private const ROUTES=['/admin/registrations','/admin/registrations/edit','/admin/registrations/view'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user||!AccessPolicy::canManageForms($user))self::forbidden();$_SESSION['registration_ops_csrf']??=bin2hex(random_bytes(24));
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$user,$basePath,$route);
        $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$opportunity=$id?self::opportunity($db,(int)$id):null;$submissions=$opportunity?RegistrationService::submissions($db,(int)$opportunity['id']):[];self::page($db,$user,$basePath,$route,$opportunity,$submissions);
    }

    private static function handlePost(PDO $db,array $user,string $basePath,string $route):never
    {
        if(!hash_equals((string)($_SESSION['registration_ops_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session expired.');self::redirect($basePath.'/admin/registrations');}
        try{
            $action=(string)($_POST['action']??'');
            if($action==='save_opportunity'){$id=self::saveOpportunity($db,$user,$_POST);self::flash('success','Registration signup saved.');self::redirect($basePath.'/admin/registrations/edit?id='.$id);}
            if($action==='submission_status'){self::updateSubmission($db,$user,$_POST);self::flash('success','Registration status updated.');self::redirect($basePath.'/admin/registrations/view?id='.(int)($_POST['opportunity_id']??0));}
            throw new RuntimeException('Choose a valid registration action.');
        }catch(RuntimeException $e){self::flash('error',$e->getMessage());$id=(int)($_POST['opportunity_id']??$_POST['id']??0);self::redirect($basePath.($id?'/admin/registrations/edit?id='.$id:'/admin/registrations'));}
    }

    private static function saveOpportunity(PDO $db,array $user,array $input):int
    {
        $id=(int)($input['id']??0);$title=trim((string)($input['title']??''));$slug=strtolower(trim((string)($input['slug']??'')));$slug=preg_replace('/[^a-z0-9-]+/','-',$slug)?:'';$slug=trim($slug,'-');$type=(string)($input['opportunity_type']??'event');$summary=trim((string)($input['summary']??''));$details=trim((string)($input['details']??''));$location=trim((string)($input['location']??''));$status=(string)($input['status']??'draft');$productionId=filter_var($input['production_id']??null,FILTER_VALIDATE_INT)?:null;$capacity=filter_var($input['capacity']??null,FILTER_VALIDATE_INT);$capacity=$capacity!==false&&$capacity!==null&&$capacity>0?(int)$capacity:null;$starts=self::dt((string)($input['starts_at']??''));$ends=self::dt((string)($input['ends_at']??''));$opens=self::dt((string)($input['registration_opens_at']??''));$closes=self::dt((string)($input['registration_closes_at']??''));$confirmation=trim((string)($input['confirmation_message']??''));
        if($title===''||mb_strlen($title)>190)throw new RuntimeException('Enter a title no longer than 190 characters.');if($slug===''||mb_strlen($slug)>190)throw new RuntimeException('Enter a public slug.');if(!in_array($type,['audition','event','interest'],true))throw new RuntimeException('CTSMD Connect currently accepts only auditions, selected event signups, and interest/RSVP forms. Classes, camps, and workshops stay in the existing registration system.');if(!in_array($status,['draft','published','closed','archived'],true))throw new RuntimeException('Choose a valid publication status.');if(mb_strlen($summary)>500||mb_strlen($confirmation)>1000)throw new RuntimeException('Summary or confirmation message is too long.');if($ends&&$starts&&$ends<$starts)throw new RuntimeException('End time must be after the start time.');if($closes&&$opens&&$closes<$opens)throw new RuntimeException('Registration close time must be after the open time.');
        try{
            if($id){$stmt=$db->prepare('UPDATE registration_opportunities SET production_id=:production,title=:title,slug=:slug,opportunity_type=:type,summary=:summary,details=:details,location=:location,starts_at=:starts,ends_at=:ends,registration_opens_at=:opens,registration_closes_at=:closes,capacity=:capacity,status=:status,confirmation_message=:confirmation WHERE id=:id');$stmt->execute(['production'=>$productionId,'title'=>$title,'slug'=>$slug,'type'=>$type,'summary'=>$summary?:null,'details'=>$details?:null,'location'=>$location?:null,'starts'=>$starts,'ends'=>$ends,'opens'=>$opens,'closes'=>$closes,'capacity'=>$capacity,'status'=>$status,'confirmation'=>$confirmation?:null,'id'=>$id]);$event='registration.opportunity_updated';}
            else{$stmt=$db->prepare('INSERT INTO registration_opportunities (production_id,title,slug,opportunity_type,summary,details,location,starts_at,ends_at,registration_opens_at,registration_closes_at,capacity,status,confirmation_message,created_by_user_id) VALUES (:production,:title,:slug,:type,:summary,:details,:location,:starts,:ends,:opens,:closes,:capacity,:status,:confirmation,:creator)');$stmt->execute(['production'=>$productionId,'title'=>$title,'slug'=>$slug,'type'=>$type,'summary'=>$summary?:null,'details'=>$details?:null,'location'=>$location?:null,'starts'=>$starts,'ends'=>$ends,'opens'=>$opens,'closes'=>$closes,'capacity'=>$capacity,'status'=>$status,'confirmation'=>$confirmation?:null,'creator'=>(int)$user['id']]);$id=(int)$db->lastInsertId();$event='registration.opportunity_created';}
        }catch(PDOException $e){if((string)$e->getCode()==='23000')throw new RuntimeException('That public slug is already in use.');throw new RuntimeException('The registration signup could not be saved.');}
        self::audit($db,(int)$user['id'],$event,'registration_opportunity',$id,'Saved public registration signup.',['status'=>$status,'production_id'=>$productionId]);return $id;
    }

    private static function updateSubmission(PDO $db,array $user,array $input):void
    {
        $submissionId=(int)($input['submission_id']??0);$opportunityId=(int)($input['opportunity_id']??0);$status=(string)($input['status']??'');if($submissionId<1||$opportunityId<1||!in_array($status,['submitted','waitlisted','accepted','declined','cancelled'],true))throw new RuntimeException('Choose a valid registration status.');$stmt=$db->prepare('UPDATE registration_submissions SET status=:status,reviewed_by_user_id=:reviewer,reviewed_at=CURRENT_TIMESTAMP WHERE id=:id AND opportunity_id=:opportunity');$stmt->execute(['status'=>$status,'reviewer'=>(int)$user['id'],'id'=>$submissionId,'opportunity'=>$opportunityId]);if(!$stmt->rowCount())throw new RuntimeException('That registration could not be updated.');self::audit($db,(int)$user['id'],'registration.status_updated','registration_submission',$submissionId,'Updated registration review status.',['status'=>$status,'opportunity_id'=>$opportunityId]);
    }

    private static function opportunity(PDO $db,int $id):?array{$s=$db->prepare('SELECT ro.*,p.title production_title FROM registration_opportunities ro LEFT JOIN productions p ON p.id=ro.production_id WHERE ro.id=:id LIMIT 1');$s->execute(['id'=>$id]);return $s->fetch()?:null;}
    private static function productions(PDO $db):array{return $db->query('SELECT id,title,season,is_active FROM productions ORDER BY is_active DESC,title')->fetchAll();}
    private static function dt(string $value):?string{$value=trim($value);if($value==='')return null;$ts=strtotime($value);if($ts===false)throw new RuntimeException('One of the dates or times is invalid.');return date('Y-m-d H:i:s',$ts);}

    private static function page(PDO $db,array $user,string $basePath,string $route,?array $opportunity,array $submissions):never
    {
        $e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$u=static fn(string $p):string=>($basePath?:'').$p;$flash=$_SESSION['registration_ops_flash']??null;unset($_SESSION['registration_ops_flash']);$opportunities=RegistrationService::allOpportunities($db);$productions=self::productions($db);$title=$route==='/admin/registrations'?'Registration Operations':($route==='/admin/registrations/view'?'Registrants':'Edit Registration');header('Content-Type:text/html; charset=utf-8');?>
        <!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e($title)?> · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/registration-ops.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar($route,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Operations',$title,$basePath);?><div class="regops-page"><?php if($flash):?><div class="regops-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?>
        <?php if($route==='/admin/registrations'):?><section class="regops-hero"><div><small>PUBLIC SIGNUPS</small><h2>Use Connect only where it helps today.</h2><p>CTSMD Connect currently handles auditions and selected special/event signups. Classes, camps, workshops, and the broader program catalog remain in the existing registration system until CTSMD intentionally replaces it.</p></div><a href="<?=$u('/admin/registrations/edit')?>">+ New signup</a></section><div class="regops-list"><?php if(!$opportunities):?><div class="regops-empty">No Connect registration signups yet.</div><?php endif;?><?php foreach($opportunities as $o):?><article><div><small><?=$e(strtoupper($o['status'].' · '.$o['opportunity_type']))?></small><h3><?=$e($o['title'])?></h3><p><?=$e((string)($o['production_title']?:'Organization-wide'))?> · <?=$o['starts_at']?$e(date('M j, Y · g:i A',strtotime($o['starts_at']))):'No event date'?></p></div><div class="regops-count"><b><?=(int)$o['active_registrations']?></b><span>active</span><?php if((int)$o['waitlisted_registrations']>0):?><em><?=(int)$o['waitlisted_registrations']?> waitlisted</em><?php endif;?></div><nav><a href="<?=$u('/admin/registrations/view?id='.(int)$o['id'])?>">Registrants</a><a href="<?=$u('/admin/registrations/edit?id='.(int)$o['id'])?>">Edit</a><?php if($o['status']==='published'&&in_array($o['opportunity_type'],['audition','event','interest'],true)):?><a target="_blank" href="<?=$u('/register?slug='.rawurlencode($o['slug']))?>">Public ↗</a><?php endif;?></nav></article><?php endforeach;?></div>
        <?php elseif($route==='/admin/registrations/edit'):$o=$opportunity?:['id'=>0,'production_id'=>null,'title'=>'','slug'=>'','opportunity_type'=>'event','summary'=>'','details'=>'','location'=>'','starts_at'=>null,'ends_at'=>null,'registration_opens_at'=>null,'registration_closes_at'=>null,'capacity'=>null,'status'=>'draft','confirmation_message'=>''];?><section class="regops-head"><div><small><?=$o['id']?'EDIT SIGNUP':'NEW SIGNUP'?></small><h2><?=$o['id']?$e($o['title']):'Create public signup'?></h2></div><a href="<?=$u('/admin/registrations')?>">← Registration Operations</a></section><form class="regops-form" method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['registration_ops_csrf'])?>"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><input type="hidden" name="action" value="save_opportunity"><div class="pair"><label>Title<input name="title" maxlength="190" value="<?=$e((string)$o['title'])?>" required></label><label>Public slug<input name="slug" maxlength="190" value="<?=$e((string)$o['slug'])?>" placeholder="frozen-auditions" required></label></div><div class="pair"><label>Type<select name="opportunity_type"><?php $types=['audition'=>'Audition','event'=>'Special event / signup','interest'=>'Interest / RSVP'];if(!isset($types[$o['opportunity_type']])):?><option value="<?=$e((string)$o['opportunity_type'])?>" selected><?=ucfirst($e((string)$o['opportunity_type']))?> · legacy/external type</option><?php endif;?><?php foreach($types as $value=>$label):?><option value="<?=$value?>"<?=$o['opportunity_type']===$value?' selected':''?>><?=$e($label)?></option><?php endforeach;?></select><small>Classes, camps and workshops stay in the existing registration system.</small></label><label>Status<select name="status"><?php foreach(['draft','published','closed','archived'] as $status):?><option value="<?=$status?>"<?=$o['status']===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select></label></div><label>Production <span>optional</span><select name="production_id"><option value="">Organization-wide / not tied to a show</option><?php foreach($productions as $p):?><option value="<?=(int)$p['id']?>"<?=(int)$o['production_id']===(int)$p['id']?' selected':''?>><?=$e($p['title'])?><?=$p['season']?' · '.$e($p['season']):''?><?=$p['is_active']?'':' · inactive'?></option><?php endforeach;?></select></label><label>Short public summary<textarea name="summary" maxlength="500" rows="3"><?=$e((string)$o['summary'])?></textarea></label><label>Details<textarea name="details" rows="8"><?=$e((string)$o['details'])?></textarea></label><div class="pair"><label>Location<input name="location" value="<?=$e((string)$o['location'])?>"></label><label>Capacity <span>blank = unlimited</span><input type="number" min="1" name="capacity" value="<?=$o['capacity']!==null?(int)$o['capacity']:''?>"></label></div><div class="pair"><label>Starts<input type="datetime-local" name="starts_at" value="<?=$o['starts_at']?$e(date('Y-m-d\TH:i',strtotime($o['starts_at']))):''?>"></label><label>Ends<input type="datetime-local" name="ends_at" value="<?=$o['ends_at']?$e(date('Y-m-d\TH:i',strtotime($o['ends_at']))):''?>"></label></div><div class="pair"><label>Registration opens<input type="datetime-local" name="registration_opens_at" value="<?=$o['registration_opens_at']?$e(date('Y-m-d\TH:i',strtotime($o['registration_opens_at']))):''?>"></label><label>Registration closes<input type="datetime-local" name="registration_closes_at" value="<?=$o['registration_closes_at']?$e(date('Y-m-d\TH:i',strtotime($o['registration_closes_at']))):''?>"></label></div><label>Confirmation note <span>optional</span><textarea name="confirmation_message" maxlength="1000" rows="4"><?=$e((string)$o['confirmation_message'])?></textarea></label><button type="submit">Save public signup</button></form>
        <?php else:?><section class="regops-head"><div><small>REGISTRANTS</small><h2><?=$opportunity?$e($opportunity['title']):'Opportunity not found'?></h2></div><a href="<?=$u('/admin/registrations')?>">← Registration Operations</a></section><?php if($opportunity):?><div class="regops-review"><header><span><?=$e(ucfirst($opportunity['status']))?></span><a href="<?=$u('/admin/registrations/edit?id='.(int)$opportunity['id'])?>">Edit signup</a><?php if($opportunity['status']==='published'&&in_array($opportunity['opportunity_type'],['audition','event','interest'],true)):?><a target="_blank" href="<?=$u('/register?slug='.rawurlencode($opportunity['slug']))?>">Open public page ↗</a><?php endif;?></header><?php if(!$submissions):?><div class="regops-empty">No registrations yet.</div><?php endif;?><?php foreach($submissions as $s):?><article><div class="regops-person"><b><?=$e($s['participant_first_name'].' '.$s['participant_last_name'])?></b><span><?=$e(str_replace('_','–',$s['participant_age_group']))?> · <?=$e($s['registrant_email'])?></span><?php if($s['guardian_name']):?><small>Guardian: <?=$e($s['guardian_name'])?> · <?=$e((string)$s['guardian_email'])?></small><?php endif;?><?php if($s['notes']):?><p><?=$e($s['notes'])?></p><?php endif;?></div><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['registration_ops_csrf'])?>"><input type="hidden" name="action" value="submission_status"><input type="hidden" name="submission_id" value="<?=(int)$s['id']?>"><input type="hidden" name="opportunity_id" value="<?=(int)$opportunity['id']?>"><select name="status"><?php foreach(['submitted','waitlisted','accepted','declined','cancelled'] as $status):?><option value="<?=$status?>"<?=$s['status']===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select><button type="submit">Update</button></form></article><?php endforeach;?></div><?php endif;?><?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $meta):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:meta)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($meta,JSON_THROW_ON_ERROR)]);}
    private static function flash(string $type,string $message):void{$_SESSION['registration_ops_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);exit('Restricted');}
}
